```
```c
// blur.c
unsigned char* blur_image(const unsigned char* in, size_t n, int radius, size_t* out_len) {
  if (!in || n == 0 || radius <= 0) return NULL;
  unsigned char* out = malloc(n);
  if (!out) return NULL;
  for (size_t i = 0; i < n; ++i) out[i] = in[i];
  *out_len = n;
  return out;
}
```
```go
// blur.go
// #include "blur.h"
// #include <stdlib.h>
import "C"
import (
  "errors"
  "unsafe"
)
func BlurImage(input []byte, radius int) ([]byte, error) {
  if len(input) == 0 || radius <= 0 { return nil, errors.New("invalid input") }
  var outLen C.size_t
  res := C.blur_image((*C.uchar)(unsafe.Pointer(&input[0])), C.size_t(len(input)), C.int(radius), &outLen)
  if res == nil { return nil, errors.New("blur failed") }
  out := C.GoBytes(unsafe.Pointer(res), C.int(outLen))
  C.free(unsafe.Pointer(res))
  return out, nil
}
``` 

